/**
 * Sitemap contract builder (Prompt 10).
 *
 * The entries of an academy's `sitemap.xml`, for the website overview's
 * read-only preview. The served file is generated by the backend
 * (`public-website/utils/seo-files.util.ts`, B0-WEB-01) and Caddy sends
 * `/sitemap.xml` on academy hosts there; this builder follows the same
 * rules so the preview lists what is served: nothing unless the website
 * is published, search engines are allowed and the sitemap is on; only
 * VISIBLE, INDEXABLE pages, at their public path (`resolvePagePath`: the
 * course-details template is never a URL of its own), each path once.
 */
import { resolvePagePath } from './link-resolution.utils';
import type {
  BlogPost,
  Course,
  SitemapEntry,
  WebsiteConfiguration,
  WebsitePage,
} from '@types';

export interface BuildSitemapEntriesInput {
  readonly configuration: WebsiteConfiguration;
  readonly pages: readonly WebsitePage[];
  readonly courses?: readonly Course[];
  readonly blogPosts?: readonly BlogPost[];
}

export function buildSitemapEntries({
  configuration,
  pages,
  courses = [],
  blogPosts = [],
}: BuildSitemapEntriesInput): readonly SitemapEntry[] {
  // The website itself must be published, and both search-engine indexing
  // and the sitemap must be on, before anything is listed — the server
  // serves no sitemap otherwise.
  if (
    configuration.status !== 'published' ||
    configuration.seo.robotsIndexable === false ||
    configuration.seo.sitemapEnabled === false
  ) {
    return [];
  }

  const seen = new Set<string>();
  const pageEntries: SitemapEntry[] = [];
  for (const page of pages) {
    if (!page.visible || page.seo.indexable === false) continue;
    const path = resolvePagePath(page);
    if (!path || seen.has(path)) continue;
    seen.add(path);
    pageEntries.push({
      path,
      lastModified: page.updatedAt,
      changeFrequency: page.coreType === 'home' ? 'weekly' : 'monthly',
      priority: page.coreType === 'home' ? 1 : 0.6,
    });
  }

  const courseEntries: SitemapEntry[] = courses
    .filter(
      (course) =>
        course.status === 'published' && course.visibility === 'public'
    )
    .map((course) => ({
      path: `/courses/${course.slug}`,
      lastModified: course.updatedAt,
      changeFrequency: 'weekly',
      priority: 0.8,
    }));

  const blogEntries: SitemapEntry[] = blogPosts
    .filter((post) => post.status === 'published')
    .map((post) => ({
      path: `/blog/${post.slug}`,
      lastModified: post.updatedAt,
      changeFrequency: 'monthly',
      priority: 0.5,
    }));

  return [...pageEntries, ...courseEntries, ...blogEntries];
}
